(function() {
  // Find chat list container by structural pattern:
  // - Parent contains multiple children with position: absolute
  // - Each child is a conversation item with timestamp and name div
  let chatContainer = null;
  const containers = document.querySelectorAll('div[style*="position: absolute"]');

  for (let container of containers) {
    const parent = container.parentElement;
    if (!parent) continue;

    const siblings = Array.from(parent.children);
    // Chat list usually has 5-30 items
    if (siblings.length >= 5 && siblings.length <= 30) {
      // Verify it's the chat list by checking for timestamp and name elements
      const hasTimestamp = !!parent.querySelector('abbr.timestamp');
      const hasNameDiv = !!parent.querySelector('div.x1vvvo52.x1fvot60.xxio538');

      if (hasTimestamp && hasNameDiv) {
        chatContainer = parent;
        break;
      }
    }
  }

  if (!chatContainer) {
    return { error: 'Chat container not found' };
  }

  // Extract chat items
  const items = Array.from(chatContainer.children);
  const chats = [];

  items.forEach(item => {
    try {
      const text = item.textContent || '';

      // Skip if too short or empty
      if (text.length < 10) return;

      // Find name element by class pattern
      const nameEl = item.querySelector('div.x1vvvo52.x1fvot60.xxio538');
      const name = nameEl ? nameEl.textContent.trim() : '';

      // Find time using timestamp element
      const timeEl = item.querySelector('abbr.timestamp');
      const time = timeEl ? timeEl.textContent.trim() : '';

      // Find last message preview
      // Look for divs that contain message content (usually short text with <=3 children)
      const allDivs = item.querySelectorAll('div');
      let lastMsg = '';
      for (let div of allDivs) {
        const divText = div.textContent.trim();
        // Message preview typically 10-300 chars, has few children
        if (divText.length > 10 && divText.length < 300 && div.children.length <= 3) {
          // Skip if it's just the name or time
          if (divText === name || divText === time) continue;

          // Clean up: remove name prefix if present
          let cleaned = divText;
          if (cleaned.startsWith(name)) {
            cleaned = cleaned.substring(name.length).trim();
          }

          // Take the first suitable message preview
          if (cleaned.length > 5) {
            lastMsg = cleaned.substring(0, 100);
            break;
          }
        }
      }

      // Check unread status by font weight
      const nameStyle = nameEl ? window.getComputedStyle(nameEl) : null;
      const unread = nameStyle && (nameStyle.fontWeight === 'bold' || parseInt(nameStyle.fontWeight) >= 600);

      if (name) {
        chats.push({
          name: name,
          time: time || '',
          lastMsg: lastMsg || '',
          unread: !!unread
        });
      }
    } catch (e) {
      // Skip items that fail to parse
    }
  });

  return chats;
})()

(function() {
  // Find all message bubbles in the conversation
  // Messages are identified by specific background colors:
  // - Blue (rgb(10, 124, 255)) = our replies
  // - Gray (rgb(239, 239, 239) or similar) = customer messages

  const allDivs = document.querySelectorAll('div');
  const messages = [];
  const processedImages = new Set();

  // First pass: collect text messages
  for (let div of allDivs) {
    const text = div.textContent.trim();

    // Skip if text is too short or too long
    if (text.length < 2 || text.length > 1000) continue;

    // Check background color
    const bg = window.getComputedStyle(div).backgroundColor;
    const match = bg.match(/rgb\((\d+),\s*(\d+),\s*(\d+)\)/);
    if (!match) continue;

    const [_, r, g, b] = match.map(Number);

    let isCustomer = null;

    // Blue background = our message
    if (b > 200 && r < 50 && g > 100 && g < 150) {
      isCustomer = false;
    }
    // Gray/white background = customer message  
    else if (r > 200 && g > 200 && b > 200) {
      isCustomer = true;
    }

    // Skip if not a message bubble
    if (isCustomer === null) continue;

    // Check if this div has the common message class pattern
    const className = div.className || '';
    if (!className.includes('x1y1aw1k')) continue;

    // Avoid duplicate messages (parent containers may also match)
    // Only take messages with relatively few children
    if (div.children.length > 5) continue;

    // Check for duplicates
    const isDuplicate = messages.some(m => m.text === text);
    if (isDuplicate) continue;

    messages.push({
      text: text,
      isCustomer: isCustomer,
      hasImage: false,
      imageUrl: null,
      bg: bg
    });
  }

  // Second pass: find standalone images (photos without text bubbles)
  const images = document.querySelectorAll('img[src*="fbcdn.net"]');
  for (let img of images) {
    // Only process large images (actual message photos, not icons/avatars)
    if (img.width < 100 || img.height < 100) continue;
    if (processedImages.has(img.src)) continue;

    // Filter out link preview images (external.*.fna.fbcdn.net)
    // Only keep actual uploaded photos (scontent-*.xx.fbcdn.net)
    if (img.src.includes('external.') && img.src.includes('.fna.fbcdn.net')) {
      continue;
    }

    // Images in Facebook Messenger are typically customer messages (left side)
    // unless they're in a blue bubble container
    processedImages.add(img.src);

    messages.push({
      text: '[Image]',
      isCustomer: true,  // Assume customer sent it
      hasImage: true,
      imageUrl: img.src,
      bg: 'image'
    });
  }

  // Reverse to show chronological order (oldest first)
  return messages.reverse();
})()

#!/usr/bin/env node
/**
 * Meta Facebook Inbox Setup Wizard
 * Supports multiple Facebook pages with custom aliases.
 * Run: node setup.js
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

const CONFIG_PATH = path.join(__dirname, '..', 'config.json');
const DEFAULT_ALIAS = 'fb fanpage';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

function question(prompt) {
  return new Promise(resolve => rl.question(prompt, resolve));
}

function loadConfig() {
  if (fs.existsSync(CONFIG_PATH)) {
    return JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
  }
  return { pages: [] };
}

function saveConfig(config) {
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(config, null, 2) + '\n', 'utf8');
}

function validateUrl(url) {
  return url.startsWith('https://business.facebook.com/') || url.startsWith('https://www.facebook.com/');
}

function showPages(pages) {
  if (pages.length === 0) {
    console.log('  (no pages configured)\n');
    return;
  }
  pages.forEach((p, i) => {
    console.log(`  ${i + 1}. [${p.alias}] ${p.url}`);
  });
  console.log('');
}

async function addPage(config) {
  console.log('\n📋 Instructions:');
  console.log('  1. Open Meta Business Suite in your browser');
  console.log('  2. Go to the Inbox of your Facebook page');
  console.log('  3. Copy the full URL from the address bar');
  console.log('     (e.g. https://business.facebook.com/latest/inbox/all/?&asset_id=123456)\n');

  let url = '';
  while (!url) {
    const input = await question('Paste the Facebook Inbox URL: ');
    const trimmed = input.trim();
    if (!trimmed) {
      console.log('❌ URL cannot be empty.\n');
      continue;
    }
    if (!validateUrl(trimmed)) {
      console.log('❌ URL must start with https://business.facebook.com/ or https://www.facebook.com/\n');
      continue;
    }
    url = trimmed;
  }

  const aliasInput = await question(`Give this page an alias (default: "${DEFAULT_ALIAS}"): `);
  const alias = aliasInput.trim() || DEFAULT_ALIAS;

  // Check for duplicate alias
  const existing = config.pages.find(p => p.alias === alias);
  if (existing) {
    const overwrite = await question(`⚠️  Alias "${alias}" already exists. Overwrite? (y/N): `);
    if (overwrite.toLowerCase() !== 'y') {
      console.log('Skipped.\n');
      return;
    }
    existing.url = url;
  } else {
    config.pages.push({ alias, url });
  }

  saveConfig(config);
  console.log(`\n✅ Page saved: [${alias}] ${url}\n`);
}

async function removePage(config) {
  if (config.pages.length === 0) {
    console.log('No pages to remove.\n');
    return;
  }
  showPages(config.pages);
  const num = await question('Enter page number to remove (or 0 to cancel): ');
  const idx = parseInt(num, 10) - 1;
  if (idx < 0 || idx >= config.pages.length) {
    console.log('Cancelled.\n');
    return;
  }
  const removed = config.pages.splice(idx, 1)[0];
  saveConfig(config);
  console.log(`✅ Removed: [${removed.alias}]\n`);
}

async function main() {
  console.log('\n🔧 Meta Facebook Inbox Setup\n');

  const config = loadConfig();

  console.log('Current pages:');
  showPages(config.pages);

  let running = true;
  while (running) {
    const choice = await question('What would you like to do?\n  1. Add a page\n  2. Remove a page\n  3. Done\n\nChoice (1/2/3): ');
    switch (choice.trim()) {
      case '1':
        await addPage(config);
        break;
      case '2':
        await removePage(config);
        break;
      case '3':
      default:
        running = false;
        break;
    }
  }

  console.log('Current configuration:');
  showPages(config.pages);
  console.log('Setup complete. You can re-run this script anytime to add or remove pages.\n');
  rl.close();
}

main().catch(err => {
  console.error('Error:', err);
  rl.close();
  process.exit(1);
});
